  return <ul>{visible.map(mapItem)}</ul>;
}

import { useActionState } from 'react';

async function createItem(prevState, formData) {
  'use server';
  const name = formData.get('name');
  // Save item...
  return { id: crypto.randomUUID(), name };
}

function CreateItemForm() {
  const [state, formAction, isPending] = useActionState(createItem, null);

  return (
    <form action={formAction}>
      <input name="name" required />
      <button disabled={isPending}>
        {isPending ? 'Saving...' : 'Create'}
      </button>
      {state?.id && <p>Created {state.id}</p>}
    </form>
  );
}

import { use, Suspense } from 'react';

function Comments({ commentsPromise }) {
  // Suspends until the promise resolves
  const comments = use(commentsPromise);
  return comments.map((c) => <p key={c.id}>{c.text}</p>);
}

function Post({ id }) {
  const promise = fetch(`/api/posts/${id}/comments`).then((r) => r.json());
  return (
    <Suspense fallback={<p>Loading comments...</p>}>
      <Comments commentsPromise={promise} />
    </Suspense>
  );
}

function Input({ ref, ...props }) {
  return <input ref={ref} {...props} />;
}

function Form() {
  const inputRef = useRef();
  return <Input ref={inputRef} placeholder="Name" />;
}
